//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    opt_mem_feedback [selection]\n");
log("\n");
log("This pass detects cases where an asynchronous read port is only connected via\n");
