log("\n");
log("    -v, -vv\n");
log("        enable verbose or very verbose output\n");
log("\n");
log("    -inv\n");
log("        enable explicit handling of inverted signals\n");
log("\n");
log("    -stop <n>\n");
log("        stop after <n> reduction operations. this is mostly used for\n");
