log("\n");

log("\n");
log("    bufnorm [options] [selection]\n");
log("\n");
log("Insert buffer cells into the design as needed, to make sure that each wire\n");
log("has exactly one driving cell port, and aliasing wires are buffered using\n");
log("buffer cells, than can be chained in a canonical order.\n");
log("\n");
log("Running 'bufnorm' on the whole design enters 'buffered-normalized mode'.\n");
log("\n");
log("    -buf\n");
log("        Create $buf cells for all buffers. The default is to use $_BUF_ cells\n");
log("        for sigle-bit buffers and $buf cells only for multi-bit buffers.\n");
log("\n");
log("    -chain\n");
log("        Chain all alias wires. By default only wires with positive-valued\n");
log("        'chain' or 'keep' attribute on them are chained.\n");
log("\n");
log("    -output\n");
log("        Enable chaining of ouput ports wires.\n");
log("\n");
log("    -public\n");
log("        Enable chaining of wires wth public names.\n");
log("\n");
log("    -nochain\n");
log("        Disable chaining of wires with 'chain' attribute.\n");
log("\n");
log("    -nokeep\n");
log("        Disable chaining of wires with 'keep' attribute.\n");
log("\n");
log("    -flat\n");
log("        Alias for -nokeep and -nochain.\n");
log("\n");
log("    -nosticky\n");
log("        Disable 'sticky' behavior of output ports already driving whole\n");
log("        wires, and always enforce canonical sort order instead.\n");
log("\n");
log("    -alphasort\n");
log("        Strictly use alphanumeric sort for chain-order. (Default is\n");
log("        to chain 'keep' wires first, then ports in declaration order,\n");
log("        and then the other wires in alphanumeric sort order.)\n");
log("\n");
// log("    -noinit\n");
// log("        Do not move 'init' attributes to the wires on FF output ports.\n");
// log("\n");
log("Run 'bufnorm' with -pos, -bits, or -conn on the whole design to remove all\n");
log("$buf buffer cells and exit 'buffered-normalized mode' again.\n");
log("\n");
log("    -pos\n");
log("        Create (multi- and single-bit) $pos cells instead $buf and $_BUF_.\n");
log("\n");
log("    -bits\n");
log("        Create arrays of $_BUF_ cells instead of multi-bit $buf cells.\n");
log("\n");
log("    -conn\n");
log("        Create 'direct connections' instead of buffer cells.\n");
log("\n");
log("    -nomode\n");
log("        Do not automatically enter or leave 'buffered-normalized mode'.\n");
log("\n");
log("The 'bufnorm' command can also be used to just switch in and out of\n");
log("'buffered-normalized mode' and run the low-level re-normalizer.\n");
log("\n");
log("    -update\n");
log("        Enter 'buffered-normalized mode' and (re-)normalize.\n");
log("\n");
log("    -reset\n");
log("        Leave 'buffered-normalized mode' without changing the netlist.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    bwmxumap [options] [selection]\n");
log("\n");
log("This pass replaces $bwmux cells with equivalent logic\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    cellmatch -lib <design> [module selection]\n");
log("\n");
log("This pass identifies functionally equivalent counterparts between each of the\n");
log("selected modules and a module from the secondary design <design>. For every such\n");
log("correspondence found, a techmap rule is generated for mapping instances of the\n");
log("former to instances of the latter. This techmap rule is saved in yet another\n");
log("design called '$cellmatch', which is created if non-existent.\n");
log("\n");
log("This pass restricts itself to combinational modules. Modules are functionally\n");
log("equivalent as long as their truth tables are identical upto a permutation of\n");
log("inputs and outputs. The supported number of inputs is limited to 6.\n");
log("\n");
log("    cellmatch -derive_luts [module selection]\n");
log("\n");
log("For every port in each selected module, characterize its combinational\n");
log("function with a 'lut' attribute if possible.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    clkbufmap [options] [selection]\n");
log("\n");
log("Inserts clock buffers between nets connected to clock inputs and their drivers.\n");
log("\n");
log("In the absence of any selection, all wires without the 'clkbuf_inhibit'\n");
log("attribute will be considered for clock buffer insertion.\n");
log("Alternatively, to consider all wires without the 'buffer_type' attribute set to\n");
log("'none' or 'bufr' one would specify:\n");
log("  'w:* a:buffer_type=none a:buffer_type=bufr %%u %%d'\n");
log("as the selection.\n");
log("\n");
log("    -buf <celltype> <portname_out>:<portname_in>\n");
log("        Specifies the cell type to use for the clock buffers\n");
log("        and its port names.  The first port will be connected to\n");
log("        the clock network sinks, and the second will be connected\n");
log("        to the actual clock source.\n");
log("\n");
log("    -inpad <celltype> <portname_out>:<portname_in>\n");
log("        If specified, a PAD cell of the given type is inserted on\n");
log("        clock nets that are also top module's inputs (in addition\n");
log("        to the clock buffer, if any).\n");
log("\n");
log("At least one of -buf or -inpad should be specified.\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    clockgate [options] [selection]\n");
log("\n");
log("This pass transforms each set of FFs sharing the same clock and\n");
log("enable signal into a clock-gating cell and a set of enable-less FFs.\n");
log("Primarily a power-saving transformation on ASIC designs.\n");
log("\n");
log("    -pos <celltype> <ce>:<clk>:<gclk>\n");
log("        If specified, rising-edge FFs will have CE inputs\n");
log("        removed and a gated clock will be created by the\n");
log("        user-specified <celltype> ICG (integrated clock gating)\n");
log("        cell with ports named <ce>, <clk>, <gclk>.\n");
log("        The ICG's clock enable pin must be active high.\n");
log("    -neg <celltype> <ce>:<clk>:<gclk>\n");
log("        If specified, falling-edge FFs will have CE inputs\n");
log("        removed and a gated clock will be created by the\n");
log("        user-specified <celltype> ICG (integrated clock gating)\n");
log("        cell with ports named <ce>, <clk>, <gclk>.\n");
log("        The ICG's clock enable pin must be active high.\n");
log("    -liberty <filename>\n");
log("        If specified, ICGs will be selected from the liberty files\n");
log("        if available. Priority is given to cells with fewer tie_lo\n");
log("        inputs and smaller size. This removes the need to manually\n");
log("        specify -pos or -neg and -tie_lo.\n");
log("    -dont_use <celltype>\n");
log("        Cells <celltype> won't be considered when searching for ICGs\n");
log("        in the liberty file specified by -liberty.\n");
log("    -tie_lo <port_name>\n");
log("        Port <port_name> of the ICG will be tied to zero.\n");
log("        Intended for DFT scan-enable pins.\n");
log("    -min_net_size <n>\n");
log("        Only transform sets of at least <n> eligible FFs.\n");
log("        \n");

log("\n");
log("    constmap [options] [selection]\n");
log("\n");
log("Map constants to a driver cell.\n");
log("\n");
log("    -cell <celltype> <portname> <paramname>\n");
log("        Replace constant bits with this cell.\n");
log("        The value of the constant will be stored to the parameter specified.\n");
log("\n");

log("\n");
log("    deminout [options] [selection]\n");
log("\n");
log("\"Demote\" inout ports to input or output ports, if possible.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    demuxmap [selection]\n");
log("\n");
log("This pass transforms $demux cells to a bunch of equality comparisons.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    dffinit [options] [selection]\n");
log("\n");
log("This pass sets an FF cell parameter to the the initial value of the net it\n");
log("drives. (This is primarily used in FPGA flows.)\n");
log("\n");
log("    -ff <cell_name> <output_port> <init_param>\n");
log("        operate on the specified cell type. this option can be used\n");
log("        multiple times.\n");
log("\n");
log("    -highlow\n");
log("        use the string values \"high\" and \"low\" to represent a single-bit\n");
log("        initial value of 1 or 0. (multi-bit values are not supported in this\n");
log("        mode.)\n");
log("\n");
log("    -strinit <string for high> <string for low> \n");
log("        use string values in the command line to represent a single-bit\n");
log("        initial value of 1 or 0. (multi-bit values are not supported in this\n");
log("        mode.)\n");
log("\n");
log("    -noreinit\n");
log("        fail if the FF cell has already a defined initial value set in other\n");
log("        passes and the initial value of the net it drives is not equal to\n");
log("        the already defined initial value.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    dfflegalize [options] [selection]\n");
log("\n");
log("Converts FFs to types supported by the target.\n");
log("\n");
log("    -cell <cell_type_pattern> <init_values>\n");
log("        specifies a supported group of FF cells.  <cell_type_pattern>\n");
log("        is a yosys internal fine cell name, where ? characters can be\n");
log("        as a wildcard matching any character.  <init_values> specifies\n");
log("        which initialization values these FF cells can support, and can\n");
log("        be one of:\n");
log("\n");
log("        - x (no init value supported)\n");
log("        - 0\n");
log("        - 1\n");
log("        - r (init value has to match reset value, only for some FF types)\n");
log("        - 01 (both 0 and 1 supported).\n");
log("\n");
log("    -mince <num>\n");
log("        specifies a minimum number of FFs that should be using any given\n");
log("        clock enable signal.  If a clock enable signal doesn't meet this\n");
log("        threshold, it is unmapped into soft logic.\n");
log("\n");
log("    -minsrst <num>\n");
log("        specifies a minimum number of FFs that should be using any given\n");
log("        sync set/reset signal.  If a sync set/reset signal doesn't meet this\n");
log("        threshold, it is unmapped into soft logic.\n");
log("\n");
log("The following cells are supported by this pass (ie. will be ingested,\n");
log("and can be specified as allowed targets):\n");
log("\n");
log("- $_DFF_[NP]_\n");
log("- $_DFFE_[NP][NP]_\n");
log("- $_DFF_[NP][NP][01]_\n");
log("- $_DFFE_[NP][NP][01][NP]_\n");
log("- $_ALDFF_[NP][NP]_\n");
log("- $_ALDFFE_[NP][NP][NP]_\n");
log("- $_DFFSR_[NP][NP][NP]_\n");
log("- $_DFFSRE_[NP][NP][NP][NP]_\n");
log("- $_SDFF_[NP][NP][01]_\n");
log("- $_SDFFE_[NP][NP][01][NP]_\n");
log("- $_SDFFCE_[NP][NP][01][NP]_\n");
log("- $_SR_[NP][NP]_\n");
log("- $_DLATCH_[NP]_\n");
log("- $_DLATCH_[NP][NP][01]_\n");
log("- $_DLATCHSR_[NP][NP][NP]_\n");
log("\n");
log("The following transformations are performed by this pass:\n");
log("\n");
log("- upconversion from a less capable cell to a more capable cell, if the less\n");
log("  capable cell is not supported (eg. dff -> dffe, or adff -> dffsr)\n");
log("- unmapping FFs with clock enable (due to unsupported cell type or -mince)\n");
log("- unmapping FFs with sync reset (due to unsupported cell type or -minsrst)\n");
log("- adding inverters on the control pins (due to unsupported polarity)\n");
log("- adding inverters on the D and Q pins and inverting the init/reset values\n");
log("  (due to unsupported init or reset value)\n");
log("- converting sr into adlatch (by tying D to 1 and using E as set input)\n");
log("- emulating unsupported dffsr cell by adff + adff + sr + mux\n");
log("- emulating unsupported dlatchsr cell by adlatch + adlatch + sr + mux\n");
log("- emulating adff when the (reset, init) value combination is unsupported by\n");
log("  dff + adff + dlatch + mux\n");
log("- emulating adlatch when the (reset, init) value combination is unsupported by\n");
log("- dlatch + adlatch + dlatch + mux\n");
log("If the pass is unable to realize a given cell type (eg. adff when only plain dff\n");
log("is available), an error is raised.\n");

log("\n");
log("    dfflibmap [-prepare] [-map-only] [-info] [-dont_use <cell_name>] -liberty <file> [selection]\n");
log("\n");
log("Map internal flip-flop and latch cells to the flip-flop and latch cells in the\n");
log("technology library specified in the given liberty files.\n");
log("\n");
log("This pass may add inverters as needed. Therefore it is recommended to\n");
log("first run this pass and then map the logic paths to the target technology.\n");
log("\n");
log("When called with -prepare, this command will convert the internal FF/latch cells\n");
log("to the internal cell types that best match the cells found in the given\n");
log("liberty file, but won't actually map them to the target cells.\n");
log("\n");
log("When called with -map-only, this command will only map internal cell\n");
log("types that are already of exactly the right type to match the target\n");
log("cells, leaving remaining internal cells untouched.\n");
log("\n");
log("When called with -info, this command will only print the target cell\n");
log("list, along with their associated internal cell types, and the arguments\n");
log("that would be passed to the dfflegalize pass.  The design will not be\n");
log("changed.\n");
log("\n");
log("When called with -dont_use, this command will not map to the specified cell\n");
log("name as an alternative to setting the dont_use property in the Liberty file.\n");
log("This argument can be called multiple times with different cell names. This\n");
log("argument also supports simple glob patterns in the cell name.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    dffunmap [options] [selection]\n");
log("\n");
log("This pass transforms FF types with clock enable and/or synchronous reset into\n");
log("their base type (with neither clock enable nor sync reset) by emulating the\n");
log("clock enable and synchronous reset with multiplexers on the cell input.\n");
log("\n");
log("    -ce-only\n");
log("        unmap only clock enables, leave synchronous resets alone.\n");
log("\n");
log("    -srst-only\n");
log("        unmap only synchronous resets, leave clock enables alone.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    extract -map <map_file> [options] [selection]\n");
log("    extract -mine <out_file> [options] [selection]\n");
log("\n");
log("This pass looks for subcircuits that are isomorphic to any of the modules\n");
log("in the given map file and replaces them with instances of this modules. The\n");
log("map file can be a Verilog source file (*.v) or an RTLIL source file (*.il).\n");
log("\n");
log("    -map <map_file>\n");
log("        use the modules in this file as reference. This option can be used\n");
log("        multiple times.\n");
log("\n");
log("    -map %%<design-name>\n");
log("        use the modules in this in-memory design as reference. This option can\n");
log("        be used multiple times.\n");
log("\n");
log("    -verbose\n");
log("        print debug output while analyzing\n");
log("\n");
log("    -constports\n");
log("        also find instances with constant drivers. this may be much\n");
log("        slower than the normal operation.\n");
log("\n");
log("    -nodefaultswaps\n");
log("        normally builtin port swapping rules for internal cells are used per\n");
log("        default. This turns that off, so e.g. 'a^b' does not match 'b^a'\n");
log("        when this option is used.\n");
log("\n");
log("    -compat <needle_type> <haystack_type>\n");
log("        Per default, the cells in the map file (needle) must have the\n");
log("        type as the cells in the active design (haystack). This option\n");
log("        can be used to register additional pairs of types that should\n");
log("        match. This option can be used multiple times.\n");
log("\n");
log("    -swap <needle_type> <port1>,<port2>[,...]\n");
log("        Register a set of swappable ports for a needle cell type.\n");
log("        This option can be used multiple times.\n");
log("\n");
log("    -perm <needle_type> <port1>,<port2>[,...] <portA>,<portB>[,...]\n");
log("        Register a valid permutation of swappable ports for a needle\n");
log("        cell type. This option can be used multiple times.\n");
log("\n");
log("    -cell_attr <attribute_name>\n");
log("        Attributes on cells with the given name must match.\n");
log("\n");
log("    -wire_attr <attribute_name>\n");
log("        Attributes on wires with the given name must match.\n");
log("\n");
log("    -ignore_parameters\n");
log("        Do not use parameters when matching cells.\n");
log("\n");
log("    -ignore_param <cell_type> <parameter_name>\n");
log("        Do not use this parameter when matching cells.\n");
log("\n");
log("This pass does not operate on modules with unprocessed processes in it.\n");
log("(I.e. the 'proc' pass should be used first to convert processes to netlists.)\n");
log("\n");
log("This pass can also be used for mining for frequent subcircuits. In this mode\n");
log("the following options are to be used instead of the -map option.\n");
log("\n");
log("    -mine <out_file>\n");
log("        mine for frequent subcircuits and write them to the given RTLIL file\n");
log("\n");
log("    -mine_cells_span <min> <max>\n");
log("        only mine for subcircuits with the specified number of cells\n");
log("        default value: 3 5\n");
log("\n");
log("    -mine_min_freq <num>\n");
log("        only mine for subcircuits with at least the specified number of matches\n");
log("        default value: 10\n");
log("\n");
log("    -mine_limit_matches_per_module <num>\n");
