//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    extract_counter [options] [selection]\n");
log("\n");
log("This pass converts non-resettable or async resettable counters to counter cells.\n");
