log("    -minwidth N\n");
log("        Only extract counters at least N bits wide (default 2)\n");
log("\n");
log("    -allow_arst yes|no\n");
log("        Allow counters to have async reset (default yes)\n");
log("\n");
log("    -dir up|down|both\n");
log("        Look for up-counters, down-counters, or both (default down)\n");
log("\n");
log("    -pout X,Y,...\n");
log("        Only allow parallel output from the counter to the listed cell types\n");
log("        (if not specified, parallel outputs are not restricted)\n");
log("\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    extract_fa [options] [selection]\n");
log("\n");
log("This pass extracts full/half adders from a gate-level design.\n");
log("\n");
log("    -fa, -ha\n");
log("        Enable cell types (fa=full adder, ha=half adder)\n");
log("        All types are enabled if none of this options is used\n");
log("\n");
log("    -d <int>\n");
log("        Set maximum depth for extracted logic cones (default=20)\n");
log("\n");
log("    -b <int>\n");
log("        Set maximum breadth for extracted logic cones (default=6)\n");
log("\n");
log("    -v\n");
log("        Verbose output\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    extract_reduce [options] [selection]\n");
log("\n");
log("converts gate chains into $reduce_* cells\n");
log("\n");
log("This command finds chains of $_AND_, $_OR_, and $_XOR_ cells and replaces them\n");
log("with their corresponding $reduce_* cells. Because this command only operates on\n");
log("these cell types, it is recommended to map the design to only these cell types\n");
log("using the `abc -g` command. Note that, in some cases, it may be more effective\n");
log("to map the design to only $_AND_ cells, run extract_reduce, map the remaining\n");
log("parts of the design to AND/OR/XOR cells, and run extract_reduce a second time.\n");
log("\n");
log("    -allow-off-chain\n");
log("        Allows matching of cells that have loads outside the chain. These cells\n");
log("        will be replicated and folded into the $reduce_* cell, but the original\n");
log("        cell will remain, driving its original loads.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    extractinv [options] [selection]\n");
log("\n");
log("Searches the design for all cells with invertible pins controlled by a cell\n");
log("parameter (eg. IS_CLK_INVERTED on many Xilinx cells) and removes the parameter.\n");
log("If the parameter was set to 1, inserts an explicit inverter cell in front of\n");
log("the pin instead.  Normally used for output to ISE, which does not support the\n");
log("inversion parameters.\n");
log("\n");
log("To mark a cell port as invertible, use (* invertible_pin = \"param_name\" *)\n");
log("on the wire in the blackbox module.  The parameter value should have\n");
log("the same width as the port, and will be effectively XORed with it.\n");
log("\n");
log("    -inv <celltype> <portname_out>:<portname_in>\n");
log("        Specifies the cell type to use for the inverters and its port names.\n");
log("        This option is required.\n");
log("\n");

log("\n");
log("    hilomap [options] [selection]\n");
log("\n");
log("Map constants to 'tielo' and 'tiehi' driver cells.\n");
log("\n");
log("    -hicell <celltype> <portname>\n");
log("        Replace constant hi bits with this cell.\n");
log("\n");
log("    -locell <celltype> <portname>\n");
log("        Replace constant lo bits with this cell.\n");
log("\n");
log("    -singleton\n");
log("        Create only one hi/lo cell and connect all constant bits\n");
log("        to that cell. Per default a separate cell is created for\n");
log("        each constant bit.\n");
log("\n");

log("\n");
log("    insbuf [options] [selection]\n");
log("\n");
log("Insert buffer cells into the design for directly connected wires.\n");
log("\n");
log("    -buf <celltype> <in-portname> <out-portname>\n");
log("        Use the given cell type instead of $_BUF_. (Notice that the next\n");
log("        call to \"clean\" will remove all $_BUF_ in the design.)\n");
log("\n");
log("    -chain\n");
log("        Chain buffer cells\n");
log("\n");

log("\n");
log("    iopadmap [options] [selection]\n");
log("\n");
log("Map module inputs/outputs to PAD cells from a library. This pass\n");
log("can only map to very simple PAD cells. Use 'techmap' to further map\n");
log("the resulting cells to more sophisticated PAD cells.\n");
log("\n");
log("    -inpad <celltype> <in_port>[:<ext_port>]\n");
log("        Map module input ports to the given cell type with the\n");
log("        given output port name. if a 2nd portname is given, the\n");
log("        signal is passed through the pad cell, using the 2nd\n");
log("        portname as the port facing the module port.\n");
log("\n");
log("    -outpad <celltype> <out_port>[:<ext_port>]\n");
log("    -inoutpad <celltype> <io_port>[:<ext_port>]\n");
log("        Similar to -inpad, but for output and inout ports.\n");
log("\n");
log("    -toutpad <celltype> <oe_port>:<out_port>[:<ext_port>]\n");
log("        Merges $_TBUF_ cells into the output pad cell. This takes precedence\n");
log("        over the other -outpad cell. The first portname is the enable input\n");
log("        of the tristate driver, which can be prefixed with `~` for negative\n");
log("        polarity enable.\n");
log("\n");
log("    -tinoutpad <celltype> <oe_port>:<in_port>:<out_port>[:<ext_port>]\n");
log("        Merges $_TBUF_ cells into the inout pad cell. This takes precedence\n");
log("        over the other -inoutpad cell. The first portname is the enable input\n");
log("        of the tristate driver and the 2nd portname is the internal output\n");
log("        buffering the external signal.  Like with `-toutpad`, the enable can\n");
log("        be marked as negative polarity by prefixing the name with `~`.\n");
log("\n");
log("    -ignore <celltype> <portname>[:<portname>]*\n");
log("        Skips mapping inputs/outputs that are already connected to given\n");
