log("\n");
log("    -widthparam <param_name>\n");
log("        Use the specified parameter name to set the port width.\n");
log("\n");
log("    -nameparam <param_name>\n");
log("        Use the specified parameter to set the port name.\n");
log("\n");
log("    -bits\n");
log("        create individual bit-wide buffers even for ports that\n");
log("        are wider. (the default behavior is to create word-wide\n");
log("        buffers using -widthparam to set the word size on the cell.)\n");
log("\n");
log("Tristate PADS (-toutpad, -tinoutpad) always operate in -bits mode.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    libcache {-enable|-disable|-purge} { -all | [path]... }\n");
log("\n");
log("Controls the default and per path caching of liberty file data.\n");
log("\n");
log("    -enable    Enable caching.\n");
log("    -disable   Disable caching.\n");
log("    -purge     Reset cache setting and forget cached data.\n");
log("\n");
log("This mode takes a list of paths as argument. If no paths are provided, this\n");
log("command does nothing. The -all option can be used to change the default cache\n");
log("setting for -enable/-disable or to reset and forget about all paths.\n");
log("\n");
log("By default caching is disabled.\n");
log("\n");
log("    libcache -scl {-enable|-disable}\n");
log("\n");
log("Controls the on-disk cache of merged SCL files that the abc and abc9 passes\n");
