log("\n");
log("    libcache -scl -dir [path]\n");
log("\n");
log("Stores the merged SCL files in [path] instead of a directory of this user in\n");
log("the temp directory. <empty> means a per user directory in the temp directory.\n");
log("\n");
log("    libcache -list\n");
log("\n");
log("Displays the current cache settings and cached paths.\n");
log("\n");
log("    libcache {-verbose|-quiet}\n");
log("\n");
log("Controls cache use logging.\n");
log("\n");
log("    -verbose   Enable printing info when cache is used\n");
log("    -quiet     Disable printing info when cache is used (default)\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    lut2bmux [options] [selection]\n");
