log("    lut2mux [options] [selection]\n");
log("\n");
log("This pass converts $lut cells to $mux/$_MUX_ gates.\n");
log("\n");
log("    -word\n");
log("        Convert $lut cells with a single input to word-level $mux gates.\n");
log("   	   The default is to convert them to bit-level $_MUX_ gates.\n");
log("\n");

//   |---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|---v---|
log("\n");
log("    maccmap [-unmap] [selection]\n");
log("\n");
log("This pass maps $macc cells to yosys $fa and $alu cells. When the -unmap option\n");
log("is used then the $macc cell is mapped to $add, $sub, etc. cells instead: a\n");
